function readInput(name) {
  try { return String($input.get(name) ?? '').trim(); } catch (e) { return ''; }
}
// Se quitan comillas y barras para que el texto no rompa el cuerpo JSON del HTTP.
const consulta = readInput('consulta').replace(/["\\\n\r\t]/g, ' ').slice(0, 200);
const idMarca = readInput('id_marca').replace(/[^0-9]/g, '');
$context.set('consulta', consulta);
$context.set('id_marca', idMarca);

const response = $context.getHttpResponse('buscarResponse');
let payload = {};
try {
  payload = response.json();
} catch (e) {
  throw new Error('Respuesta inválida de veh-bdc');
}
// veh-bdc responde {ok, tipo, data}. 'vacio' es una respuesta válida: no hay coincidencias.
if (payload.tipo !== 'ok' && payload.tipo !== 'vacio') {
  throw new Error('Búsqueda no disponible: ' + String(payload.tipo || 'error'));
}
const data = payload.data || {};
const resultados = (data.resultados || []).slice(0, 12).map(function (r) {
  return {
    marca: r.marca,
    id_marca: r.id_marca != null ? String(r.id_marca) : '',
    id_modelo: r.id_modelo != null ? String(r.id_modelo) : '',
    sku: r.sku,
    nombre: r.nombre,
    segmento: r.segmento,
    precio: r.precio,
    moneda: r.moneda || 'USD',
    etiquetas: r.etiquetas || [],
    coincidencia: r.coincidencia
  };
});
const exactas = resultados.filter(function (r) { return r.coincidencia === 'exacta'; });
const marcasExactas = Array.from(new Set(exactas.map(function (r) { return r.id_marca; })));
$output.set('success', {
  ok: true,
  tipo: payload.tipo,
  consulta: $context.get('consulta') || null,
  total: resultados.length,
  total_exactas: exactas.length,
  marcas: data.marcas || [],
  marcas_exactas: marcasExactas,
  resultados: resultados,
  message: resultados.length
    ? ('Se encontraron ' + exactas.length + ' coincidencia(s) exacta(s) y ' + (resultados.length - exactas.length) + ' relacionada(s).')
    : 'No hay vehículos que coincidan con esa búsqueda.'
});
